import AppKit
import Observation
import QuickLookThumbnailing
import SwiftUI

/// Finder-style previews of local files, generated by the system off the main actor and
/// kept for the app's lifetime. A file that is gone or has no preview gets the drawn stand-in.
@MainActor
@Observable
final class ThumbnailCache {
    private var images: [String: NSImage] = [:]
    @ObservationIgnored private var requested: Set<String> = []
    /// Produces the preview; replaced in tests and offscreen renders.
    @ObservationIgnored private let generate: @Sendable (URL, CGFloat, CGFloat) async -> CGImage?

    init(generate: @escaping @Sendable (URL, CGFloat, CGFloat) async -> CGImage? = ThumbnailCache.quickLook) {
        self.generate = generate
    }

    /// The cached preview, if it has been generated. Starts generating it otherwise.
    func image(for path: String, side: CGFloat, scale: CGFloat) -> NSImage? {
        let key = "\(Int(side))|\(path)"
        if let image = images[key] { return image }
        if requested.insert(key).inserted {
            Task {
                guard let cgImage = await generate(URL(fileURLWithPath: path), side, scale) else { return }
                images[key] = NSImage(
                    cgImage: cgImage,
                    size: CGSize(width: CGFloat(cgImage.width) / scale, height: CGFloat(cgImage.height) / scale))
            }
        }
        return nil
    }

    @Sendable
    nonisolated static func quickLook(_ url: URL, side: CGFloat, scale: CGFloat) async -> CGImage? {
        let request = QLThumbnailGenerator.Request(
            fileAt: url, size: CGSize(width: side, height: side), scale: scale,
            representationTypes: [.thumbnail, .icon])
        return try? await QLThumbnailGenerator.shared.generateBestRepresentation(for: request).cgImage
    }
}

/// The preview of an uploaded file, fitted inside a square of `side` points.
struct ThumbnailView: View {
    let path: String
    let fileName: String
    var side: CGFloat = 30
    @Environment(ThumbnailCache.self) private var cache
    @Environment(\.displayScale) private var displayScale

    var body: some View {
        if let image = cache.image(for: path, side: side, scale: displayScale) {
            Image(nsImage: image)
                .resizable()
                .interpolation(.high)
                .aspectRatio(contentMode: .fit)
                .frame(maxWidth: side, maxHeight: side)
                .shadow(color: .black.opacity(0.25), radius: 1.5, y: 1)
        } else {
            GenericFileIcon(fileName: fileName, height: side * 28 / 30)
        }
    }
}

/// The mockups' stand-in for a file with no preview: a small page with its extension.
struct GenericFileIcon: View {
    let fileName: String
    var height: CGFloat = 28

    var body: some View {
        let label = String((fileName as NSString).pathExtension.uppercased().prefix(4))
        RoundedRectangle(cornerRadius: 2)
            .fill(Theme.dynamic(0xF4F5F8, 0xF4F5F8))
            .overlay(alignment: .bottom) {
                Text(label)
                    .font(.system(size: max(height * 6 / 28, 5), weight: .bold))
                    .foregroundStyle(Theme.dynamic(0x7A8094, 0x7A8094))
                    .padding(.bottom, height * 3 / 28)
            }
            .overlay { RoundedRectangle(cornerRadius: 2).strokeBorder(.black.opacity(0.2), lineWidth: 1) }
            .frame(width: height * 22 / 28, height: height)
            .shadow(color: .black.opacity(0.25), radius: 1.5, y: 1)
    }
}
